const exportTombstones = `-- name: ExportTombstones :many
SELECT entity_id::text AS entity_id, deleted_at
FROM tombstone
WHERE entity = $1::text
  AND deleted_at > $2::timestamptz
  AND (deleted_at, entity_id) > ($3::timestamptz, $4::uuid)
ORDER BY deleted_at, entity_id
LIMIT $5::int
`

type ExportTombstonesParams struct {
	Entity  string
	Since   pgtype.Timestamptz
	AfterAt pgtype.Timestamptz
	AfterID pgtype.UUID
	Batch   int32
}

type ExportTombstonesRow struct {
	EntityID  string
	DeletedAt pgtype.Timestamptz
}

// One entity at a time, because each entity's deletions belong in its own data file - and because
// the primary key starts (tenant_id, entity), so asking for one entity is an index range rather
// than a scan. Paged on (deleted_at, entity_id) for the reason every statement above is: a page
// that repeated or skipped a row would put a tombstone in one archive and nowhere else.
func (q *Queries) ExportTombstones(ctx context.Context, arg ExportTombstonesParams) ([]ExportTombstonesRow, error) {
	rows, err := q.db.Query(ctx, exportTombstones,
		arg.Entity,
		arg.Since,
		arg.AfterAt,
		arg.AfterID,
		arg.Batch,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ExportTombstonesRow{}
	for rows.Next() {
		var i ExportTombstonesRow
		if err := rows.Scan(&i.EntityID, &i.DeletedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

